  Subscription SelectedProfile(){if(subscriptions==null||subscriptions.SelectedItems.Count==0)throw new InvalidOperationException("请先选中一个订阅。");return (Subscription)subscriptions.SelectedItems[0].Tag;}
  void FillProfiles(string selectId=null){if(subscriptions==null||subscriptions.IsDisposed)return;var bookmark=ViewBookmark.Capture(subscriptions);if(subscriptions.Items.Count==0)bookmark=profileBookmark;string selected=selectId??(bookmark==null?store.State.Active:bookmark.Selected);var existing=subscriptions.Items.Cast<ListViewItem>().ToDictionary(x=>((Subscription)x.Tag).Id);bool reveal=selectId!=null&&(bookmark==null||bookmark.Selected!=selectId);var ids=new HashSet<string>(store.State.Profiles.Select(x=>x.Id));if(selected!=null&&!ids.Contains(selected))selected=store.State.Profiles.Count==0?null:store.State.Profiles[Math.Min(bookmark==null?0:bookmark.SelectedIndex,store.State.Profiles.Count-1)].Id;subscriptions.BeginUpdate();try{foreach(var item in existing.Values)if(!ids.Contains(((Subscription)item.Tag).Id))subscriptions.Items.Remove(item);foreach(var profile in store.State.Profiles){string[] values={(store.State.Active==profile.Id?"●  ":"")+profile.Name,String.IsNullOrEmpty(profile.Url)?"本地":"订阅",NiceDate(profile.Updated),profile.Usage??""};ListViewItem item;if(!existing.TryGetValue(profile.Id,out item)){item=new ListViewItem(values){Tag=profile};subscriptions.Items.Add(item);}else for(int i=0;i<values.Length;i++)if(item.SubItems[i].Text!=values[i])item.SubItems[i].Text=values[i];item.Tag=profile;item.Selected=profile.Id==selected;}}finally{subscriptions.EndUpdate();}if(bookmark!=null)RestoreAfterLayout(subscriptions,bookmark,selected,reveal);if(reveal){var item=subscriptions.Items.Cast<ListViewItem>().FirstOrDefault(x=>((Subscription)x.Tag).Id==selectId);if(item!=null)item.EnsureVisible();}if(page==1)subtitle.Text=store.State.Profiles.Count==0?"还没有订阅：添加链接，或把 YAML 文件拖进窗口。":"共 "+store.State.Profiles.Count+" 个订阅 · 双击应用，拖入 YAML 可直接导入。";RefreshActions();}
  static string NiceDate(string s){DateTime d;return DateTime.TryParse(s,out d)?d.ToLocalTime().ToString("MM-dd HH:mm"):s;}
  void ImportUrl(){using(var dialog=new SubscriptionDialog(null,engine.Running)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string name=dialog.NameValue,url=dialog.UrlValue;bool proxy=dialog.ThroughProxy;Subscription created=null;Run(delegate{var result=Engine.Download(url,proxy,store.State.Port);engine.Validate(engine.Build(result.Yaml));created=new Subscription(){Name=SubscriptionNames.Resolve(name,result.Name,url),AutoName=String.IsNullOrWhiteSpace(name),Url=url,Usage=result.Usage,Updated=DateTime.UtcNow.ToString("o")};Store.Atomic(store.ProfilePath(created),result.Yaml);AddProfile(created);},delegate{FillProfiles(created.Id);AddLog("已导入订阅："+created.Name);Feedback("已导入 "+created.Name+"，可在概览连接代理。");});}}
  void ImportFile(){using(var d=new OpenFileDialog(){Filter="YAML 配置|*.yaml;*.yml|所有文件|*.*",Title="导入 Clash / mihomo 配置"}){if(d.ShowDialog(this)==DialogResult.OK)ImportDroppedFile(d.FileName);}}
  void AddProfile(Subscription profile){string oldActive=store.State.Active;store.State.Profiles.Add(profile);if(String.IsNullOrEmpty(oldActive))store.State.Active=profile.Id;try{store.Save();}catch{store.State.Profiles.Remove(profile);store.State.Active=oldActive;File.Delete(store.ProfilePath(profile));throw;}}
  void ActivateProfile(){try{var s=SelectedProfile();Run(delegate{var before=store.Active;string oldActive=store.State.Active;string yaml=File.ReadAllText(store.ProfilePath(s));engine.Apply(s,yaml);store.State.Active=s.Id;try{store.Save();}catch{store.State.Active=oldActive;if(engine.Running){if(before!=null)engine.Apply(before,File.ReadAllText(store.ProfilePath(before)));else engine.Stop();}throw;}},delegate{FillProfiles(s.Id);RefreshState();AddLog("当前订阅："+s.Name);});}catch(Exception ex){Error(ex);}}
  void CommitProfile(Subscription profile,string yaml,Action metadata){var before=Store.Json.Deserialize<Subscription>(Store.Json.Serialize(profile));string path=store.ProfilePath(profile),old=yaml==null?null:File.ReadAllText(path);bool active=yaml!=null&&engine.Running&&engine.ActiveId==profile.Id;
   if(yaml!=null){if(active)engine.Apply(profile,yaml);else engine.Validate(engine.Build(yaml));}
   try{if(yaml!=null&&old!=yaml)Store.Atomic(path,yaml);metadata();store.Save();}catch(Exception original){profile.Name=before.Name;profile.Url=before.Url;profile.AutoName=before.AutoName;profile.Updated=before.Updated;profile.Usage=before.Usage;try{if(yaml!=null&&old!=yaml)Store.Atomic(path,old);if(active)engine.Apply(profile,old);}catch(Exception rollback){throw new IOException("保存失败，回退配置也未完成："+rollback.Message,original);}throw;}
  }
  void RefreshProfile(Subscription s,bool viaProxy){if(String.IsNullOrEmpty(s.Url))return;var result=Engine.Download(s.Url,viaProxy,store.State.Port);CommitProfile(s,result.Yaml,delegate{s.Updated=DateTime.UtcNow.ToString("o");s.Usage=result.Usage;SubscriptionNames.ApplyDownloaded(s,result);});AddLog("订阅已更新："+s.Name);}
  void UpdateSelected(){try{var s=SelectedProfile();if(String.IsNullOrEmpty(s.Url))throw new InvalidOperationException("本地配置没有订阅链接。请用“导入 YAML”导入新版文件，或编辑配置后重新应用。");bool via=false;using(var d=new DownloadDialog(engine.Running)){if(d.ShowDialog(this)!=DialogResult.OK)return;via=d.ThroughProxy;}Run(delegate{RefreshProfile(s,via);},delegate{FillProfiles(s.Id);});}catch(Exception ex){Error(ex);}}
  void UpdateAll(bool automatic){if(busy)return;bool via=false;if(!automatic){using(var d=new DownloadDialog(engine.Running)){if(d.ShowDialog(this)!=DialogResult.OK)return;via=d.ThroughProxy;}}var list=store.State.Profiles.Where(x=>!String.IsNullOrEmpty(x.Url)).ToArray();Run(delegate{int failures=0;foreach(var s in list){if(automatic){DateTime last;if(DateTime.TryParse(s.Updated,out last)&&(DateTime.UtcNow-last.ToUniversalTime()).TotalHours<store.State.UpdateHours)continue;}try{RefreshProfile(s,via);}catch(Exception ex){failures++;AddLog("更新失败 ["+s.Name+"]："+ex.Message);}}if(failures>0&&!automatic)throw new IOException(failures+" 个订阅更新失败，详情见日志；原配置已保留。");},delegate{FillProfiles();});}
  void AutoUpdate(){if(!store.State.UpdateAutomatically||busy||DateTime.UtcNow<nextAuto)return;nextAuto=DateTime.UtcNow.AddMinutes(30);UpdateAll(true);}
  void EditProfile(){try{var s=SelectedProfile();using(var d=new SubscriptionDialog(s,engine.Running)){if(d.ShowDialog(this)!=DialogResult.OK)return;string name=d.NameValue,url=d.UrlValue;bool via=d.ThroughProxy;bool automatic=!String.IsNullOrEmpty(url)&&(String.IsNullOrWhiteSpace(name)||(s.AutoName&&name==s.Name));Run(delegate{DownloadResult result=null;if((url!=s.Url||String.IsNullOrWhiteSpace(name))&&!String.IsNullOrWhiteSpace(url))result=Engine.Download(url,via,store.State.Port);CommitProfile(s,result==null?null:result.Yaml,delegate{if(result!=null){s.Updated=DateTime.UtcNow.ToString("o");s.Usage=result.Usage;}s.Name=automatic?SubscriptionNames.Resolve(null,result==null?null:result.Name,url,url==s.Url?s.Name:null):SubscriptionNames.Resolve(name,null,null,s.Name);s.AutoName=automatic;s.Url=url;});},delegate{FillProfiles(s.Id);});}}catch(Exception ex){Error(ex);}}
  void DeleteProfile(){try{var s=SelectedProfile();if(engine.Running&&engine.ActiveId==s.Id)throw new InvalidOperationException("请先停止内核或切换到其他订阅，再删除正在使用的配置。");if(MessageBox.Show(this,"删除订阅“"+s.Name+"”？","删除订阅",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;Run(delegate{int index=store.State.Profiles.IndexOf(s);string oldActive=store.State.Active;store.State.Profiles.Remove(s);if(oldActive==s.Id)store.State.Active=store.State.Profiles.Count>0?store.State.Profiles[0].Id:"";try{store.Save();}catch{store.State.Profiles.Insert(index,s);store.State.Active=oldActive;throw;}try{File.Delete(store.ProfilePath(s));}catch(Exception ex){AddLog("订阅已删除，但旧缓存未能清理："+ex.Message);}},delegate{FillProfiles();});}catch(Exception ex){Error(ex);}}
