  void FillGroups(){if(groups==null||groups.IsDisposed)return;string old=groups.SelectedItem as string;string preferred=pendingGroup??old??(restoreNodeView?rememberedGroup:null)??(store.State.Mode=="global"?"GLOBAL":null);var names=proxyData.OrderBy(x=>x.Key).Where(x=>Dict(x.Value).ContainsKey("all")).Select(x=>x.Key).ToArray();
